#ifndef FE2_FLIGHT_TABLES_H
#define FE2_FLIGHT_TABLES_H

/* Native flight tables (generated by tools/flight_tables_c.py). */
#include <stdint.h>

/* Serialized player defaults consumed by the object-template decoder. */
extern const uint8_t fe2_flight_player_template[286];
/* The view marker: four lines, each two endpoints relative to its centre. */
extern const int16_t fe2_flight_view_markers[4][4];
/* Text directory: relative word offsets, then the strings. */
extern const uint8_t *fe2_flight_text_directory;
/* Offscreen target labels (text, x, y): unprojected in state 0, upper
 * left, upper right, lower left, lower right, unprojected otherwise. */
extern const uint16_t fe2_flight_label_records[6][3];
/* Pointer regions the cockpit removes (from the last). */
extern const uint8_t fe2_flight_resource_selectors[15];
/* The command widgets' rectangles: left, top, right, bottom, key. */
extern const uint16_t fe2_flight_command_rectangles[36];
enum {
    FE2_FLIGHT_COMMAND_ACTIVATE_SELECTED, FE2_FLIGHT_COMMAND_ACTIVATE_ECM,
    FE2_FLIGHT_COMMAND_ESCAPE_CAPSULE, FE2_FLIGHT_COMMAND_ENERGY_BOMB,
    FE2_FLIGHT_COMMAND_TOGGLE_CLOUD_ANALYSIS, FE2_FLIGHT_COMMAND_TOGGLE_TARGET_STATS,
    FE2_FLIGHT_COMMAND_SHIP_COMMAND
};
extern const uint8_t fe2_flight_command_keys[7];
/* Slot centres and per-kind icons (even/odd slot orientation). */
extern const uint16_t fe2_flight_equipment_slot_centres[8][2];
extern const uint16_t fe2_flight_weapon_sprites[8][2];
/* The drive name text by drive class. */
extern const uint16_t fe2_flight_status_texts[15];
/* Emitted object variants: the block of each even model 0x7a..0x98 (by
 * (model - 0x7a) / 2), then each block's eight (model, parameter) pairs. */
extern const uint8_t fe2_flight_variant_blocks[16];
extern const uint16_t fe2_flight_variants[4][8][2];

#endif
